"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId, useRef, useState } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";

import { formatWhole } from "../lib/format";
import { BlockFrame } from "../parts/block-frame";
import { PlusIcon } from "../parts/icons";
import { RollingText } from "../parts/rolling-text";
import { type AreaId, IDEAS, type Idea, NEW_IDEA } from "./feature-voting/data";
import { IdeaComposer } from "./feature-voting/idea-composer";
import { IdeaRow } from "./feature-voting/idea-row";
import { type IdeaSort, SORTS, sortIdeas } from "./feature-voting/sort";

/**
 * A public list of ideas for Fernhill. People vote and unvote, sort by top,
 * new or trending, and post an idea after the form shows the ones that look
 * the same. Rows keep their place during a vote and glide only on a re-sort.
 */
export function FeatureVoting({ className }: { className?: string }) {
  const [ideas, setIdeas] = useState<Idea[]>(IDEAS);
  const [sort, setSort] = useState<IdeaSort>("top");
  const [order, setOrder] = useState(() => sortIdeas(IDEAS, "top"));
  const [composing, setComposing] = useState(false);
  const [announcement, setAnnouncement] = useState("");
  const suggest = useRef<HTMLButtonElement>(null);
  const reduceMotion = useReducedMotion();
  const titleId = useId();
  const nextId = useRef(1);

  const total = ideas.reduce((sum, idea) => sum + idea.votes + (idea.voted ? 1 : 0), 0);
  const byId = new Map(ideas.map((idea) => [idea.id, idea]));
  const rows = order.map((id) => byId.get(id)).filter((idea): idea is Idea => idea !== undefined);

  const changeSort = (next: IdeaSort) => {
    setSort(next);
    setOrder(sortIdeas(ideas, next));
  };

  const vote = (id: string) => {
    const idea = byId.get(id);
    if (!idea) return;
    setIdeas((list) => list.map((item) => (item.id === id ? { ...item, voted: !item.voted } : item)));
    setAnnouncement(idea.voted ? `Vote removed from ${idea.title}.` : `Voted for ${idea.title}.`);
  };

  const closeComposer = () => {
    setComposing(false);
    suggest.current?.focus();
  };

  const post = (title: string, area: AreaId) => {
    const id = `new-${nextId.current++}`;
    const idea: Idea = { id, title, detail: "", status: NEW_IDEA.status, area, votes: 0, recent: 1, comments: 0, age: 0, author: "mia", voters: [], voted: true };
    setIdeas((list) => [idea, ...list]);
    // A new idea lands at the top whatever the sort, so its author sees it.
    setOrder((list) => [id, ...list]);
    setAnnouncement(`Posted ${title}. Your vote is on it.`);
    closeComposer();
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-start justify-between gap-3 px-5 pt-5 pb-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Ideas for Fernhill
          </h2>
          <p className="text-sm text-muted-foreground">Vote on what we build next. The team reads every idea.</p>
        </div>
        <Button ref={suggest} type="button" size="sm" aria-expanded={composing} onClick={() => (composing ? closeComposer() : setComposing(true))}>
          <PlusIcon aria-hidden="true" />
          Suggest an idea
        </Button>
      </header>

      <AnimatePresence initial={false}>
        {composing ? (
          <motion.div
            key="composer"
            initial={reduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }}
            animate={reduceMotion ? { opacity: 1 } : { height: "auto", opacity: 1 }}
            exit={reduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }}
            transition={{ duration: 0.24, ease: [0.2, 0, 0, 1] }}
            className="overflow-hidden border-t border-border"
          >
            <IdeaComposer ideas={ideas} onSubmit={post} onVote={vote} onCancel={closeComposer} />
          </motion.div>
        ) : null}
      </AnimatePresence>

      <div className="flex flex-wrap items-center justify-between gap-3 border-t border-border px-5 py-3">
        <SegmentedControl aria-label="Sort ideas" options={SORTS} value={sort} onValueChange={changeSort} />
        <p className="text-sm text-muted-foreground">
          <RollingText text={formatWhole(total)} className="font-medium text-foreground" /> votes
        </p>
      </div>

      <ul aria-label={`Ideas, sorted by ${sort}`} className="px-5">
        {rows.map((idea) => (
          <IdeaRow key={idea.id} idea={idea} onVote={() => vote(idea.id)} />
        ))}
      </ul>

      <p className="border-t border-border px-5 py-3 text-xs text-muted-foreground">
        {ideas.filter((idea) => idea.voted).length === 0
          ? "You have not voted yet."
          : `You voted on ${ideas.filter((idea) => idea.voted).length} of ${ideas.length} ideas.`}
      </p>
      <p role="status" className="sr-only">
        {announcement}
      </p>
    </BlockFrame>
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

