"use client";

import { type FormEvent, type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { cn } from "@/lib/utils";

import { HUE_DOT } from "../shared/people";
import { AREA_IDS, AREAS, type AreaId, type Idea, NEW_IDEA } from "./data";
import { similarIdeas } from "./similar";
import { StatusChip } from "./status-chip";
import { VoteButton } from "./vote-button";

/** Props for the form that posts a new idea. */
export interface IdeaComposerProps {
  /** Every idea on the board, searched for ones like the draft. */
  ideas: Idea[];
  onSubmit: (title: string, area: AreaId) => void;
  onVote: (id: string) => void;
  onCancel: () => void;
}

/**
 * A short form for a new idea: a title and an area. While a person types, it
 * lists ideas that look the same, each with its own vote button, so a vote
 * replaces a duplicate. Escape closes it.
 */
export function IdeaComposer({ ideas, onSubmit, onVote, onCancel }: IdeaComposerProps) {
  const [title, setTitle] = useState("");
  const [area, setArea] = useState<AreaId>(NEW_IDEA.area);
  const input = useRef<HTMLInputElement>(null);
  const inputId = useId();
  const matchesId = useId();
  const matches = similarIdeas(ideas, title);
  const ready = title.trim().length >= 6;

  useEffect(() => {
    input.current?.focus();
  }, []);

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (ready) onSubmit(title.trim(), area);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLFormElement>) => {
    if (event.key !== "Escape") return;
    event.preventDefault();
    onCancel();
  };

  return (
    <form onSubmit={submit} onKeyDown={onKeyDown} aria-label="Suggest an idea" className="flex flex-col gap-4 border-b border-border px-5 py-4">
      <div className="flex flex-col gap-1.5">
        <label htmlFor={inputId} className="text-sm font-medium">
          Your idea
        </label>
        <Input
          ref={input}
          id={inputId}
          value={title}
          onChange={(event) => setTitle(event.target.value)}
          placeholder="For example, reminders in the patient's own language"
          aria-describedby={matchesId}
          autoComplete="off"
        />
      </div>

      <div id={matchesId} aria-live="polite" className="flex flex-col gap-2">
        {matches.length > 0 ? (
          <>
            <p className="text-sm text-muted-foreground">
              {matches.length === 1 ? "1 idea looks the same." : `${matches.length} ideas look the same.`} A vote counts for more than a second post.
            </p>
            <ul className="flex flex-col gap-2">
              {matches.map((idea) => (
                <li key={idea.id} className="flex items-center gap-3">
                  <VoteButton layout="inline" title={idea.title} count={idea.votes + (idea.voted ? 1 : 0)} voted={idea.voted} onToggle={() => onVote(idea.id)} />
                  <span className="min-w-0 flex-1 truncate text-sm">{idea.title}</span>
                  <StatusChip status={idea.status} className="hidden @md:inline-flex" />
                </li>
              ))}
            </ul>
          </>
        ) : null}
      </div>

      <div className="flex flex-col gap-2">
        <span id={`${inputId}-area`} className="pb-2 text-sm font-medium">
          Area
        </span>
        <RadioGroup
          aria-labelledby={`${inputId}-area`}
          value={area}
          onValueChange={(value) => {
            const next = AREA_IDS.find((id) => id === value);
            if (next) setArea(next);
          }}
          className="flex flex-wrap"
        >
          {AREA_IDS.map((id) => (
            <label
              key={id}
              className={cn(
                "inline-flex min-h-9 cursor-pointer items-center gap-2 rounded-full border px-3 text-sm has-focus-visible:ring-2 has-focus-visible:ring-ring",
                area === id ? "border-foreground text-foreground" : "border-border text-muted-foreground hover:text-foreground",
              )}
            >
              <RadioGroupItem value={id} className="sr-only" />
              <span aria-hidden="true" className={cn("size-2.5 rounded-sm", HUE_DOT[AREAS[id].hue])} />
              {AREAS[id].label}
            </label>
          ))}
        </RadioGroup>
      </div>

      <div className="flex flex-wrap justify-end gap-2">
        <Button type="button" variant="ghost" size="sm" onClick={onCancel}>
          Cancel
        </Button>
        <Button type="submit" size="sm" disabled={!ready}>
          Post idea
        </Button>
      </div>
    </form>
  );
}

import type { Idea } from "./data";

// Short and common words say nothing about what an idea is about.
const SKIP = new Set(["with", "from", "that", "this", "when", "into", "their", "they", "have", "would", "could", "should", "about", "each", "every", "make", "more", "able", "want", "need", "please"]);

const words = (text: string) =>
  text
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((word) => word.length >= 4 && !SKIP.has(word))
    // A plural and its singular count as the same word.
    .map((word) => word.replace(/s$/, ""));

/**
 * The ideas that share the most words with a draft title, best first, so a
 * person can vote on one instead of posting it twice. Returns at most `limit`.
 */
export function similarIdeas(ideas: Idea[], draft: string, limit = 3) {
  const wanted = new Set(words(draft));
  if (wanted.size === 0) return [];
  return ideas
    .map((idea) => ({ idea, score: words(`${idea.title} ${idea.detail}`).filter((word) => wanted.has(word)).length }))
    .filter((match) => match.score > 0)
    .sort((a, b) => b.score - a.score || b.idea.votes - a.idea.votes)
    .slice(0, limit)
    .map((match) => match.idea);
}

