} satisfies Record<IdeaStatus, { label: string; tone: string; dot: string }>;

/** A small pill that names where an idea stands. */
export function StatusChip({ status, className }: { status: IdeaStatus; className?: string }) {
  const meta = IDEA_STATUS[status];
  return (
    <span className={cn("inline-flex items-center gap-1.5 rounded-full px-2 py-0.5 text-xs font-medium whitespace-nowrap", meta.tone, className)}>
      <span aria-hidden="true" className={cn("size-2 rounded-full", meta.dot)} />
      {meta.label}
