/** Props for the vote button of one idea. */
export interface VoteButtonProps {
  /** The idea's title, so the button names what it votes for. */
  title: string;
  /** The count including the viewer's vote. */
  count: number;
  voted: boolean;
  onToggle: () => void;
  /** Who voted, in words, such as "Lena Fischer, Kofi Mensah and 410 others". Shown when the button has keyboard focus or a pointer over it. */
  voters?: string;
  /** `stack` puts the count under the arrow, for a list row. `inline` puts it beside, for a compact suggestion. */
  layout?: "stack" | "inline";
  className?: string;
}

/**
 * A toggle that adds or removes the viewer's vote. The count rolls only the
 * digits that change, in tabular numerals so the width holds, and a voted
 * button fills with the primary colour. Keyboard focus shows who voted.
 */
export function VoteButton({ title, count, voted, onToggle, voters, layout = "stack", className }: VoteButtonProps) {
  const votersId = useId();
  const stack = layout === "stack";
  return (
    <span className={cn("group relative inline-flex", className)}>
      <Button
        type="button"
        variant={voted ? "default" : "outline"}
        aria-pressed={voted}
        aria-label={`Vote for ${title}`}
        aria-describedby={voters ? votersId : undefined}
        onClick={onToggle}
        size={stack ? "icon" : "sm"}
        className={cn(stack && "h-14 w-14 flex-col")}
      >
        <ChevronUpIcon aria-hidden="true" className={cn("size-4 motion-safe:transition-transform motion-safe:duration-200", voted && "-translate-y-0.5")} />
        <RollingText text={formatWhole(count)} className="text-sm" />
      </Button>
      {voters ? (
        <span
          id={votersId}
          className="pointer-events-none absolute bottom-full left-0 z-20 mb-2 hidden w-max max-w-56 rounded-lg border border-border bg-popover px-2.5 py-1.5 text-xs text-popover-foreground shadow-lg backdrop-blur-md group-hover:block group-has-focus-visible:block"
        >
          {voted ? "You, " : ""}
          {voters}
        </span>
      ) : null}
    </span>
  );
}

