import { motion, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";

import { cn } from "@/lib/utils";

import { MessageIcon } from "../../parts/icons";
import { HUE_DOT, PEOPLE } from "../shared/people";
import { AREAS, type Idea } from "./data";
import { StatusChip } from "./status-chip";
import { VoteButton } from "./vote-button";

/** The spring rows glide on when the order changes: quick, with no bounce, so nothing overshoots. */
export const REORDER_SPRING = { type: "spring", bounce: 0, duration: 0.45 } as const;

/** The voters of an idea in one phrase, such as "Lena Fischer, Kofi Mensah and 410 others". */
export function votersPhrase(idea: Idea) {
  const names = idea.voters.slice(0, 2).map((id) => PEOPLE[id].name);
  const others = idea.votes - names.length;
  return others > 0 ? `${names.join(", ")} and ${others} others` : names.join(" and ");
}

/** Props for one idea in a list. */
export interface IdeaRowProps {
  idea: Idea;
  onVote: () => void;
  /** Shows the one-line detail under the title. */
  showDetail?: boolean;
  /** Extra items at the end of the meta line, such as the author and age. */
  meta?: ReactNode;
  /** Anything under the row, such as an expanded comment thread. */
  children?: ReactNode;
  className?: string;
}

/**
 * One idea: the vote button, the title, and a meta line with the status, the
 * area and the comment count. It is a list item that glides to a new place
 * when its list is re-sorted, so a board and a voting list can share it.
 */
export function IdeaRow({ idea, onVote, showDetail = false, meta, children, className }: IdeaRowProps) {
  const reduceMotion = useReducedMotion();
  const area = AREAS[idea.area];
  const count = idea.votes + (idea.voted ? 1 : 0);
  return (
    <motion.li layout={reduceMotion ? false : "position"} transition={REORDER_SPRING} className={cn("flex flex-col border-b border-border last:border-b-0", className)}>
      <div className="flex items-start gap-4 py-3.5">
        <VoteButton title={idea.title} count={count} voted={idea.voted} onToggle={onVote} voters={votersPhrase(idea)} />
        <div className="flex min-w-0 flex-1 flex-col gap-1.5 pt-0.5">
          <h3 className="text-sm font-medium text-foreground">{idea.title}</h3>
          {showDetail ? <p className="text-sm text-muted-foreground">{idea.detail}</p> : null}
          <p className="flex flex-wrap items-center gap-x-3 gap-y-1.5 text-xs text-muted-foreground">
            <StatusChip status={idea.status} />
            <span className="inline-flex items-center gap-1.5">
              <span aria-hidden="true" className={cn("size-2.5 rounded-sm", HUE_DOT[area.hue])} />
              {area.label}
            </span>
            <span className="inline-flex items-center gap-1 tabular-nums">
              <MessageIcon aria-hidden="true" className="size-3.5" />
              {idea.comments}
              <span className="sr-only">comments</span>
            </span>
            {meta}
          </p>
        </div>
      </div>
      {children}
    </motion.li>
  );
}

import type { Idea } from "./data";

/** The three ways the list can be ordered. */
export type IdeaSort = "top" | "new" | "trending";

/** The sort choices, in the order the control shows them. */
export const SORTS: { value: IdeaSort; label: string }[] = [
  { value: "top", label: "Top" },
  { value: "new", label: "New" },
  { value: "trending", label: "Trending" },
];

const RANK = {
  top: (idea: Idea) => idea.votes + (idea.voted ? 1 : 0),
  new: (idea: Idea) => -idea.age,
  trending: (idea: Idea) => idea.recent,
} satisfies Record<IdeaSort, (idea: Idea) => number>;

/**
 * The idea ids in the order a sort puts them. A list keeps this order while
 * people vote and asks for a new one only when the sort changes, so a row
 * never moves under the pointer.
 */
export function sortIdeas(ideas: Idea[], sort: IdeaSort) {
  return [...ideas].sort((a, b) => RANK[sort](b) - RANK[sort](a)).map((idea) => idea.id);
}
